// Cada consulta: tabela do IXC + filtro. 'tag' identifica a resposta depois.
const consultas = [
  { tag: 'onus',   endpoint: 'radpop_radio_cliente_fibra', qtype: 'radpop_radio_cliente_fibra.id', query: '1', oper: '>=', sort: 'radpop_radio_cliente_fibra.id' },
  { tag: 'logins', endpoint: 'radusuarios',               qtype: 'radusuarios.ativo',             query: 'S', oper: '=',  sort: 'radusuarios.id' },
  { tag: 'ctr_A',  endpoint: 'cliente_contrato',          qtype: 'cliente_contrato.status_internet', query: 'A',  oper: '=', sort: 'cliente_contrato.id' },
  { tag: 'ctr_FA', endpoint: 'cliente_contrato',          qtype: 'cliente_contrato.status_internet', query: 'FA', oper: '=', sort: 'cliente_contrato.id' },
];
return consultas.map(c => ({ json: { ...c, page: 1, rp: 1 } }));

const reqs = $('Consultas').all();
const out = [];
$input.all().forEach((it, i) => {
  const c = reqs[i].json;
  const total = Number(it.json.total || 0);
  if (!total && c.tag !== 'ctr_FA') throw new Error(`IXC retornou total 0 em ${c.tag} - sincronizacao abortada`);
  const rp = 1000;
  for (let p = 1; p <= Math.ceil(total / rp); p++) out.push({ json: { ...c, page: p, rp, total } });
});
return out;

// LGPD: daqui pra frente so IDs e dados tecnicos. Nome, endereco, senha etc. sao descartados.
const num = v => (v === '' || v == null || isNaN(Number(v))) ? null : Number(v);
const dataOk = v => (!v || String(v).startsWith('0000')) ? null : String(v);
const reqs = $('Paginas').all();
const regs = { onus: [], logins: [], ctr_A: [], ctr_FA: [] };
const totais = {};
$input.all().forEach((it, i) => {
  const c = reqs[i].json;
  totais[c.tag] = c.total;
  for (const r of (it.json.registros || [])) regs[c.tag].push(r);
});
// Protecao: base incompleta nao grava (tolerancia de 2% para mudancas durante a paginacao)
for (const [tag, total] of Object.entries(totais)) {
  if (regs[tag].length < total * 0.98) throw new Error(`${tag} incompleto: ${regs[tag].length} de ${total} - sincronizacao abortada`);
}

const statusCtr = new Map();
for (const r of regs.ctr_A)  statusCtr.set(num(r.id), 'A');
for (const r of regs.ctr_FA) statusCtr.set(num(r.id), 'FA');

const logins = new Map();
for (const r of regs.logins) logins.set(num(r.id), { id_contrato: num(r.id_contrato), tipo_conexao_mapa: r.tipo_conexao_mapa || '' });

const rows = new Map();
const pend = new Map();
const comOnu = new Set();
let onuSemLogin = 0, loginInativoOuCtrFora = 0, dup = 0;

for (const o of regs.onus) {
  const idLogin = num(o.id_login);
  if (!idLogin) { onuSemLogin++; continue; }
  comOnu.add(idLogin);
  const lg = logins.get(idLogin);
  const ctr = lg ? lg.id_contrato : num(o.id_contrato);
  const st = statusCtr.get(ctr);
  if (!lg || !st) { loginInativoOuCtrFora++; continue; }
  const cto = num(o.id_caixa_ftth);
  if (!cto) { pend.set(idLogin, { id_login: idLogin, id_contrato: ctr, motivo: 'ONU sem CTO' }); continue; }
  if (rows.has(idLogin)) dup++;
  const sinal = num(o.sinal_rx);
  rows.set(idLogin, {
    id_login: idLogin,
    id_contrato: ctr,
    id_onu: num(o.id),
    id_transmissor: num(o.id_transmissor),
    ponid: o.ponid ? String(o.ponid) : null,
    id_caixa_ftth: cto,
    porta_ftth: num(o.porta_ftth),
    status_internet: st,
    sinal_rx: (sinal === null || sinal === 0) ? null : sinal,
    data_sinal: dataOk(o.data_sinal),
  });
}
// Login ativo + contrato A/FA + sem ONU (cancelado com login ativo, radio ou cadastro incompleto)
// So conexao Fibra (F). Radio 5.8/2.4 e Dedicado nao tem ONU e ficam fora.
for (const [idLogin, lg] of logins) {
  if (comOnu.has(idLogin) || !statusCtr.has(lg.id_contrato)) continue;
  if (lg.tipo_conexao_mapa !== 'F') continue;
  pend.set(idLogin, { id_login: idLogin, id_contrato: lg.id_contrato, motivo: 'fibra sem ONU' });
}
const resumo = {
  onus: regs.onus.length, logins_ativos: regs.logins.length,
  contratos_A: regs.ctr_A.length, contratos_FA: regs.ctr_FA.length,
  mapeados: rows.size, pendentes: pend.size,
  onu_sem_login: onuSemLogin, onu_login_inativo_ou_contrato_fora: loginInativoOuCtrFora, onu_duplicada_mesmo_login: dup,
};
if (!rows.size) throw new Error('Mapa vazio - sincronizacao abortada');
return [{ json: { rows: [...rows.values()], pend: [...pend.values()], resumo } }];
